var sp = app.activeDocument.pathItems[0].subPathItems[0];
for (var i = 0; i < sp.pathPoints.length; i++) {
  var p = sp.pathPoints[i];
  $.writeln(p.anchor + " " + p.kind + " in:" + p.leftDirection + " out:" + p.rightDirection);
}

function pt(x, y) {
  var p = new PathPointInfo();
  p.kind = PointKind.CORNERPOINT;
  p.anchor = [x, y]; p.leftDirection = [x, y]; p.rightDirection = [x, y];
  return p;
}

function pt(x, y) { var p = new PathPointInfo(); p.kind = PointKind.CORNERPOINT; p.anchor = [x, y]; p.leftDirection = [x, y]; p.rightDirection = [x, y]; return p; }
var sp = new SubPathInfo();
sp.operation = ShapeOperation.SHAPEXOR;
sp.closed = true;
sp.entireSubPath = [pt(100, 100), pt(400, 100), pt(250, 350)]; // PathPointInfo array
app.activeDocument.pathItems.add("Triangle", [sp]);

var path = app.activeDocument.pathItems.getByName("Logo");
for (var i = 0; i < path.subPathItems.length; i++) {
  var s = path.subPathItems[i];
  $.writeln(i + ": closed=" + s.closed + " op=" + s.operation + " points=" + s.pathPoints.length);
}

app.notifiersEnabled = true;
var n = app.notifiers.add("Opn ", File("C:/scripts/on_open.jsx"));
$.writeln(n.event + " -> " + n.eventFile.fsName);
n.remove();

var doc = app.activeDocument;
var lyr = doc.artLayers.add();
lyr.name = "Texture";
var photo = doc.artLayers.getByName("Photo");
$.writeln(doc.artLayers.length + " art layers, top = " + doc.artLayers[0].name);

var doc = app.activeDocument;
var mask = doc.channels.add();
mask.name = "Cutout";
doc.selection.selectAll(); // store() needs an active selection
doc.selection.store(mask);
$.writeln(doc.channels.length + " channels; first = " + doc.channels[0].name);

var doc = app.activeDocument;
var s = doc.colorSamplers.add([UnitValue(120, "px"), UnitValue(80, "px")]);
$.writeln(s.color.rgb.hexValue + " (" + doc.colorSamplers.length + " samplers)");

var doc = app.activeDocument;
doc.countItems.add([UnitValue(200, "px"), UnitValue(150, "px")]);
$.writeln(doc.countItems.length + " count markers");

var doc = app.documents.add(UnitValue(1080, "px"), UnitValue(1350, "px"), 72, "IG post",
  NewDocumentMode.RGB, DocumentFill.WHITE, 1, BitsPerChannelType.EIGHT, "sRGB IEC61966-2.1");
$.writeln(app.documents.length + " open");

var doc = app.activeDocument;
doc.guides.add(Direction.VERTICAL, UnitValue(540, "px"));
doc.guides.add(Direction.HORIZONTAL, UnitValue(675, "px"));
$.writeln(doc.guides.length + " guides");

var doc = app.activeDocument;
var before = doc.activeHistoryState;
// ... scripted edits ...
$.writeln(doc.historyStates.length + " states");
doc.activeHistoryState = before; // roll back

var doc = app.activeDocument;
doc.layerComps.add("Variant A", "red headline", true, true, true);
// ... change layer visibility for variant B ...
doc.layerComps.add("Variant B", "", true, true, true);
doc.layerComps.getByName("Variant A").apply();

var layers = app.activeDocument.layers;
for (var i = 0; i < layers.length; i++) {
  var l = layers[i];
  $.writeln(l.typename + ": " + l.name);
}

var doc = app.activeDocument;
var grp = doc.layerSets.add();
grp.name = "Headline";
var title = grp.artLayers.add();
title.name = "Title";

app.notifiersEnabled = true;
app.notifiers.add("Mk  ", File("C:/scripts/on_new_doc.jsx"), "Dcmn");
$.writeln(app.notifiers.length + " notifiers");

function pt(x, y) { var p = new PathPointInfo(); p.kind = PointKind.CORNERPOINT; p.anchor = [x, y]; p.leftDirection = [x, y]; p.rightDirection = [x, y]; return p; }
var sp = new SubPathInfo();
sp.operation = ShapeOperation.SHAPEXOR; sp.closed = true;
sp.entireSubPath = [pt(100, 100), pt(400, 100), pt(400, 300), pt(100, 300)];
var doc = app.activeDocument;
var path = doc.pathItems.add("Badge", [sp]);
path.makeSelection(0, true);
$.writeln(doc.pathItems.getByName("Badge").subPathItems.length);

var subs = app.activeDocument.pathItems.getByName("Logo").subPathItems;
$.writeln(subs.length + " sub paths");
var first = subs[0];

var want = "Montserrat", psName = null;
for (var i = 0; i < app.fonts.length; i++) {
  if (app.fonts[i].family == want) { psName = app.fonts[i].postScriptName; break; }
}
$.writeln(psName || "missing font");

var c = new SolidColor();
c.cmyk.cyan = 100; c.cmyk.magenta = 60; c.cmyk.yellow = 0; c.cmyk.black = 20;
app.foregroundColor = c;

var c = new SolidColor();
c.gray.gray = 75;
app.backgroundColor = c;

var c = new SolidColor();
c.hsb.hue = 210; c.hsb.saturation = 80; c.hsb.brightness = 90;
app.foregroundColor = c;
$.writeln(c.rgb.hexValue);

var c = new SolidColor();
c.lab.L = 55; c.lab.A = 70; c.lab.B = 40;
app.foregroundColor = c;

var c = new SolidColor();
c.rgb.hexValue = "FF5A1F";
$.writeln(c.rgb.red + "," + c.rgb.green + "," + c.rgb.blue);
app.foregroundColor = c;

var ps = app.activeDocument.printSettings;
$.writeln(ps.printers);
ps.copies = 1;
ps.cornerCropMarks = true;
ps.setPagePosition(DocPositionStyle.PRINTCENTERED);

var PAYLOAD = encodeURIComponent("({width: '1080'})"); // normally sent percent-encoded by the host
var args = eval(decodeURIComponent(PAYLOAD));
var w = parseInt(args.width, 10);
if (isNaN(w)) throw new Error("bad width");
var result = encodeURIComponent(uneval({ok: true, width: w, docs: app.documents.length}));

var g = app.activeDocument.guides.add(Direction.VERTICAL, UnitValue(100, "px"));
$.writeln(g.direction + " at " + g.coordinate);
g.coordinate = UnitValue(120, "px");
g.remove();

var c = new SolidColor();
c.rgb.hexValue = "1E90FF";
$.writeln(c.model + " C=" + c.cmyk.cyan + " web=" + c.nearestWebColor.hexValue);
if (!c.isEqual(app.foregroundColor)) app.foregroundColor = c;

// a Point-typed argument is a plain [x, y] array
var curve = [[0, 0], [64, 40], [190, 215], [255, 255]];
app.activeDocument.activeLayer.adjustCurves(curve);
$.writeln(curve[1].length + " values per point");

var b = app.activeDocument.activeLayer.bounds; // [left, top, right, bottom]
var w = b[2].as("px") - b[0].as("px");
$.writeln("width " + w + " px, " + b.length + " values");

var doc = app.activeDocument;
var t = doc.artLayers.add();
t.kind = LayerKind.TEXT;
t.textItem.contents = "SALE";
var photo = doc.artLayers.getByName("Photo");
photo.applyGaussianBlur(8);
photo.adjustBrightnessContrast(10, 25);

var o = new BatchOptions();
o.destination = BatchDestinationType.FOLDER;
o.destinationFolder = Folder("D:/out");
o.overrideSave = true;
o.fileNaming = [FileNamingType.DOCUMENTNAMEMIXED, FileNamingType.EXTENSIONLOWER];
o.errorFile = File("D:/out/errors.txt");
app.batch(Folder("D:/in").getFiles("*.jpg"), "Resize 1080", "PGD Actions", o);

var doc = app.activeDocument;
doc.changeMode(ChangeMode.GRAYSCALE);
var o = new BitmapConversionOptions();
o.method = BitmapConversionType.HALFTONESCREEN;
o.resolution = 300; o.frequency = 45; o.angle = 45; o.shape = BitmapHalfToneType.ROUND;
doc.changeMode(ChangeMode.BITMAP, o);

var doc = app.activeDocument;
var a = doc.channels.add();
a.name = "Sky mask";
doc.selection.selectAll(); // store() needs an active selection
doc.selection.store(a);
var h = doc.channels[0].histogram; // first component channel; names are localised
$.writeln(a.kind + " first-channel highlights: " + h[255]);

var s = app.activeDocument.colorSamplers.add([UnitValue(50, "px"), UnitValue(50, "px")]);
$.writeln(s.position + " = #" + s.color.rgb.hexValue);
s.move([UnitValue(300, "px"), UnitValue(200, "px")]);
s.remove();
